```sql
/* Рассчитываем excellence rate = numge1500 / numtsttakr, исключая деление на ноль */
/* Соединяем таблицы satscores и schools по коду школы */
/* Берём топ-3 уникальные школы по excellence rate и выводим их телефоны */
SELECT s.phone
FROM satscores AS sc
JOIN schools AS s ON s.cdscode = sc.cds
WHERE sc.numtsttakr > 0
GROUP BY s.phone, sc.cds
ORDER BY (sc.numge1500::NUMERIC / sc.numtsttakr) DESC NULLS LAST
LIMIT 3;
```

