```sql
/* Молекулы, не являющиеся канцерогенными (label = '-') */
/* Имеющие одинарные связи (bond_type = '-') между двумя атомами */
/* Топ-3 уникальных molecule_id в алфавитном порядке */
SELECT DISTINCT m."molecule_id"
FROM "molecule" m
JOIN "bond" b ON b."molecule_id" = m."molecule_id"
JOIN "connected" c ON c."bond_id" = b."bond_id"
WHERE m."label" = '-'
  AND b."bond_type" = '-'
ORDER BY m."molecule_id" ASC NULLS FIRST
LIMIT 3;
```

```sql
/* Вычисляем процент канцерогенных молекул, содержащих хлор (Cl) */
SELECT
    /* Числитель: молекулы с label = '+' и содержащие атом Cl */
    COUNT(DISTINCT CASE WHEN m."label" = '+' AND a."element" = 'cl' THEN m."molecule_id" END)::NUMERIC
    /
    /* Знаменатель: все молекулы */
    NULLIF(COUNT(DISTINCT m."molecule_id"), 0)::NUMERIC
    AS percentage
FROM "molecule" m
LEFT JOIN "atom" a
    ON a."molecule_id" = m."molecule_id";
```

