/* Вычисляем отношение количества мужских и женских супергероев */
SELECT
    SUM(CASE WHEN g."gender" = 'Male' THEN 1 ELSE 0 END)::NUMERIC
    / NULLIF(SUM(CASE WHEN g."gender" = 'Female' THEN 1 ELSE 0 END), 0) AS ratio
FROM "superhero" s
JOIN "gender" g ON s."gender_id" = g."id";

```sql
/* Считаем разницу между числом героев с голубыми глазами (colour.id = 7) и без цвета глаз (colour.id = 1) */
/* среди героев с отсутствующими данными о весе (weight_kg = 0 или NULL) */
SELECT
    SUM(CASE WHEN c."id" = 7 THEN 1 ELSE 0 END)
    - SUM(CASE WHEN c."id" = 1 THEN 1 ELSE 0 END) AS difference
FROM "superhero" s
JOIN "colour" c ON s."eye_colour_id" = c."id"
WHERE s."weight_kg" = 0 OR s."weight_kg" IS NULL;
```

